from dataclasses import replace

from autoresearch_infrastructure.programs import SolverOutput


_STYLE_DIAGNOSTIC_MARKERS = (
    "openpyxl.styles.",
    "NamedStyle object",
)
_STYLE_DIAGNOSTIC_LIMIT = 12000


def _compact_style_diagnostics(value):
    """Bound verbose library-object representations, leaving workbook data intact."""
    if isinstance(value, str):
        if (len(value) > _STYLE_DIAGNOSTIC_LIMIT
                and any(marker in value for marker in _STYLE_DIAGNOSTIC_MARKERS)):
            head, tail = value[:2200], value[-1200:]
            omitted = len(value) - len(head) - len(tail)
            return (
                head
                + f"\n[omitted {omitted} characters of verbose style-object diagnostics; "
                  "inspect specific attributes if needed]\n"
                + tail
            ), True
        return value, False
    if isinstance(value, dict):
        changed = False
        result = {}
        for key, item in value.items():
            result[key], item_changed = _compact_style_diagnostics(item)
            changed = changed or item_changed
        return (result, True) if changed else (value, False)
    if isinstance(value, list):
        changed = False
        result = []
        for item in value:
            compacted, item_changed = _compact_style_diagnostics(item)
            result.append(compacted)
            changed = changed or item_changed
        return (result, True) if changed else (value, False)
    if isinstance(value, tuple):
        changed = False
        result = []
        for item in value:
            compacted, item_changed = _compact_style_diagnostics(item)
            result.append(compacted)
            changed = changed or item_changed
        return (tuple(result), True) if changed else (value, False)
    return value, False


async def compact_verbose_style_observation(*args, **kwargs):
    """Trim oversized style reprs in task-tool observations before delivery."""
    values = list(args) + list(kwargs.values())
    call = next((v for v in values if hasattr(v, "origin")), None)
    observation = next(
        (v for v in reversed(values)
         if hasattr(v, "call_id") and hasattr(v, "result")),
        None,
    )
    if observation is None or (call is not None and call.origin != "task"):
        return observation
    result, changed = _compact_style_diagnostics(observation.result)
    return replace(observation, result=result) if changed else observation


async def solve(task, runtime):
    result = await runtime.run_harness(
        input=task.instruction,
        post_tool=compact_verbose_style_observation,
    )
    if not result.completed:
        raise RuntimeError("Solver did not complete")
    return SolverOutput(result.text)
